"use client"

import * as React from "react"
import {
  Bold,
  Italic,
  Strikethrough,
  Heading2,
  Quote,
  Code,
  Link2,
  Image as ImageIcon,
  List,
  ListOrdered,
  ListTodo,
  Table as TableIcon,
  Minus,
  Eye,
  Pencil,
  Maximize2,
  Minimize2,
  HelpCircle,
} from "lucide-react"
import { cn } from "@/lib/utils"
import { MarkdownRenderer } from "@/components/markdown-editor/markdown-renderer"

export interface MarkdownEditorProps {
  /** Controlled markdown value. */
  value?: string
  /** Initial value when uncontrolled. */
  defaultValue?: string
  /** Called whenever the markdown source changes. */
  onChange?: (value: string) => void
  /**
   * Called when an image is pasted or dropped. Resolve with the final URL
   * to use in `![alt](url)`. If omitted, images are embedded inline as
   * base64 data URLs so paste-to-upload works with zero backend.
   */
  onImageUpload?: (file: File) => Promise<string>
  /** Placeholder shown in the write tab. */
  placeholder?: string
  /** Minimum height (px) of the editing/preview area. */
  minHeight?: number
  /** Disable editing (preview-only interactions still work). */
  disabled?: boolean
  /** Show the formatting toolbar. Default: true. */
  toolbar?: boolean
  /** Autofocus the textarea on mount. */
  autoFocus?: boolean
  /** Extra class names for the outer container. */
  className?: string
}

function readFileAsDataUrl(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader()
    reader.onload = () => resolve(reader.result as string)
    reader.onerror = () => reject(reader.error)
    reader.readAsDataURL(file)
  })
}

function getDroppedImageFiles(dataTransfer: DataTransfer): File[] {
  return Array.from(dataTransfer.files).filter((f) => f.type.startsWith("image/"))
}

function getPastedImageFiles(clipboardData: DataTransfer): File[] {
  return Array.from(clipboardData.items)
    .filter((item) => item.kind === "file" && item.type.startsWith("image/"))
    .map((item) => item.getAsFile())
    .filter((f): f is File => f !== null)
}

const CHEATSHEET: { syntax: string; result: string }[] = [
  { syntax: "**bold**", result: "bold" },
  { syntax: "*italic*", result: "italic" },
  { syntax: "~~strike~~", result: "strikethrough" },
  { syntax: "`code`", result: "inline code" },
  { syntax: "# Heading", result: "heading" },
  { syntax: "> quote", result: "block quote" },
  { syntax: "- item", result: "bullet list" },
  { syntax: "1. item", result: "numbered list" },
  { syntax: "- [ ] todo", result: "task list" },
  { syntax: "[text](url)", result: "link" },
  { syntax: "![alt](url)", result: "image" },
  { syntax: "```lang", result: "code block" },
]

function ToolbarButton({
  icon: Icon,
  label,
  shortcut,
  onClick,
  disabled,
}: {
  icon: React.ComponentType<{ className?: string }>
  label: string
  shortcut?: string
  onClick: () => void
  disabled?: boolean
}) {
  return (
    <button
      type="button"
      title={shortcut ? `${label} (${shortcut})` : label}
      aria-label={label}
      disabled={disabled}
      onMouseDown={(e) => e.preventDefault()}
      onClick={onClick}
      className="flex h-7 w-7 items-center justify-center rounded-md text-muted-foreground transition-colors hover:bg-accent hover:text-accent-foreground disabled:pointer-events-none disabled:opacity-40"
    >
      <Icon className="h-3.5 w-3.5" />
    </button>
  )
}

function ToolbarDivider() {
  return <div className="mx-0.5 h-4 w-px bg-border" />
}

/**
 * MarkdownEditor — a GitHub-style markdown editor with Write / Preview tabs,
 * a formatting toolbar, keyboard shortcuts, and a fullscreen mode. Self
 * contained: only depends on lucide-react, the `cn` helper, and the
 * companion `MarkdownRenderer`. No extra runtime dependencies.
 */
export function MarkdownEditor({
  value: controlledValue,
  defaultValue = "",
  onChange,
  onImageUpload,
  placeholder = "Write something...",
  minHeight = 240,
  disabled = false,
  toolbar = true,
  autoFocus = false,
  className,
}: MarkdownEditorProps) {
  const isControlled = controlledValue !== undefined
  const [internalValue, setInternalValue] = React.useState(defaultValue)
  const value = isControlled ? controlledValue! : internalValue

  const [tab, setTab] = React.useState<"write" | "preview">("write")
  const [fullscreen, setFullscreen] = React.useState(false)
  const [helpOpen, setHelpOpen] = React.useState(false)
  const [isDragActive, setIsDragActive] = React.useState(false)

  const textareaRef = React.useRef<HTMLTextAreaElement>(null)
  const helpRef = React.useRef<HTMLDivElement>(null)
  const valueRef = React.useRef(value)

  React.useEffect(() => {
    valueRef.current = value
  }, [value])

  const setValue = React.useCallback(
    (next: string) => {
      valueRef.current = next
      if (!isControlled) setInternalValue(next)
      onChange?.(next)
    },
    [isControlled, onChange]
  )

  React.useEffect(() => {
    if (!fullscreen) return
    const prevOverflow = document.body.style.overflow
    document.body.style.overflow = "hidden"
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") setFullscreen(false)
    }
    document.addEventListener("keydown", onKeyDown)
    return () => {
      document.body.style.overflow = prevOverflow
      document.removeEventListener("keydown", onKeyDown)
    }
  }, [fullscreen])

  React.useEffect(() => {
    if (!helpOpen) return
    const onPointerDown = (e: MouseEvent) => {
      if (helpRef.current && !helpRef.current.contains(e.target as Node)) setHelpOpen(false)
    }
    document.addEventListener("mousedown", onPointerDown)
    return () => document.removeEventListener("mousedown", onPointerDown)
  }, [helpOpen])

  const focusTextarea = React.useCallback((start: number, end: number) => {
    requestAnimationFrame(() => {
      const el = textareaRef.current
      if (!el) return
      el.focus()
      el.setSelectionRange(start, end)
    })
  }, [])

  const wrapSelection = React.useCallback(
    (before: string, after: string = before, placeholder2 = "") => {
      const el = textareaRef.current
      if (!el) return
      const start = el.selectionStart
      const end = el.selectionEnd
      const selected = value.slice(start, end) || placeholder2
      const next = value.slice(0, start) + before + selected + after + value.slice(end)
      setValue(next)
      focusTextarea(start + before.length, start + before.length + selected.length)
    },
    [value, setValue, focusTextarea]
  )

  const prefixLines = React.useCallback(
    (prefix: string, ordered = false) => {
      const el = textareaRef.current
      if (!el) return
      const start = el.selectionStart
      const end = el.selectionEnd
      const lineStart = value.lastIndexOf("\n", start - 1) + 1
      const nextBreak = value.indexOf("\n", end)
      const lineEnd = nextBreak === -1 ? value.length : nextBreak
      const block = value.slice(lineStart, lineEnd)
      const lines = block.split("\n")
      const nonEmpty = lines.filter((l) => l.trim() !== "")
      const alreadyPrefixed = nonEmpty.length > 0 && nonEmpty.every((l) => l.startsWith(prefix))

      const newLines = lines.map((l, idx) => {
        if (l.trim() === "") return l
        if (alreadyPrefixed) return l.slice(prefix.length)
        return ordered ? `${idx + 1}. ${l}` : `${prefix}${l}`
      })
      const newBlock = newLines.join("\n")
      const next = value.slice(0, lineStart) + newBlock + value.slice(lineEnd)
      setValue(next)
      focusTextarea(lineStart, lineStart + newBlock.length)
    },
    [value, setValue, focusTextarea]
  )

  const insertAtCursor = React.useCallback(
    (text: string, selectFrom?: number, selectTo?: number) => {
      const el = textareaRef.current
      if (!el) return
      const start = el.selectionStart
      const end = el.selectionEnd
      const next = value.slice(0, start) + text + value.slice(end)
      setValue(next)
      const from = selectFrom !== undefined ? start + selectFrom : start + text.length
      const to = selectTo !== undefined ? start + selectTo : from
      focusTextarea(from, to)
    },
    [value, setValue, focusTextarea]
  )

  const insertLinkLike = React.useCallback(
    (isImage: boolean) => {
      const el = textareaRef.current
      if (!el) return
      const start = el.selectionStart
      const end = el.selectionEnd
      const selected = value.slice(start, end)
      const bang = isImage ? "!" : ""
      const label = selected || (isImage ? "alt text" : "link text")
      const text = `${bang}[${label}](https://)`
      const urlStart = text.length - "https://)".length
      const urlEnd = text.length - 1
      insertAtCursor(text, urlStart, urlEnd)
    },
    [value, insertAtCursor]
  )

  const insertImageFile = React.useCallback(
    (file: File) => {
      const el = textareaRef.current
      if (!el) return Promise.resolve()
      const start = el.selectionStart
      const end = el.selectionEnd
      const name = file.name || "image.png"
      const placeholder = `![Uploading ${name}…]()`
      const current = valueRef.current
      const next = current.slice(0, start) + placeholder + current.slice(end)
      setValue(next)
      const cursor = start + placeholder.length
      focusTextarea(cursor, cursor)

      const upload = onImageUpload ? onImageUpload(file) : readFileAsDataUrl(file)

      return upload
        .then((url) => {
          const latest = valueRef.current
          const idx = latest.indexOf(placeholder)
          if (idx === -1) return
          setValue(latest.slice(0, idx) + `![${name}](${url})` + latest.slice(idx + placeholder.length))
        })
        .catch(() => {
          const latest = valueRef.current
          const idx = latest.indexOf(placeholder)
          if (idx === -1) return
          setValue(latest.slice(0, idx) + `![Failed to upload ${name}]()` + latest.slice(idx + placeholder.length))
        })
    },
    [setValue, focusTextarea, onImageUpload]
  )

  const handlePaste = async (e: React.ClipboardEvent<HTMLTextAreaElement>) => {
    const files = getPastedImageFiles(e.clipboardData)
    if (files.length === 0) return
    e.preventDefault()
    for (const file of files) {
      await insertImageFile(file)
    }
  }

  const handleDragOver = (e: React.DragEvent<HTMLTextAreaElement>) => {
    if (Array.from(e.dataTransfer.items).some((item) => item.kind === "file")) {
      e.preventDefault()
      setIsDragActive(true)
    }
  }

  const handleDrop = async (e: React.DragEvent<HTMLTextAreaElement>) => {
    const files = getDroppedImageFiles(e.dataTransfer)
    setIsDragActive(false)
    if (files.length === 0) return
    e.preventDefault()
    for (const file of files) {
      await insertImageFile(file)
    }
  }

  const insertCodeBlock = React.useCallback(() => {
    const el = textareaRef.current
    if (!el) return
    const start = el.selectionStart
    const end = el.selectionEnd
    const selected = value.slice(start, end)
    const needsLeadingBreak = start > 0 && value[start - 1] !== "\n"
    const block = `${needsLeadingBreak ? "\n" : ""}\`\`\`\n${selected || "code"}\n\`\`\`\n`
    const codeStart = start + (needsLeadingBreak ? 1 : 0) + 4
    const codeEnd = codeStart + (selected || "code").length
    insertAtCursor(block, codeStart, codeEnd)
  }, [value, insertAtCursor])

  const insertTable = React.useCallback(() => {
    const el = textareaRef.current
    if (!el) return
    const start = el.selectionStart
    const needsLeadingBreak = start > 0 && value[start - 1] !== "\n"
    const table =
      `${needsLeadingBreak ? "\n\n" : "\n"}` +
      "| Column 1 | Column 2 | Column 3 |\n" +
      "| --- | --- | --- |\n" +
      "| Row 1 | Row 1 | Row 1 |\n" +
      "| Row 2 | Row 2 | Row 2 |\n"
    insertAtCursor(table)
  }, [value, insertAtCursor])

  const insertHr = React.useCallback(() => {
    const el = textareaRef.current
    if (!el) return
    const start = el.selectionStart
    const needsLeadingBreak = start > 0 && value[start - 1] !== "\n"
    insertAtCursor(`${needsLeadingBreak ? "\n\n" : ""}---\n`)
  }, [value, insertAtCursor])

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    const meta = e.metaKey || e.ctrlKey
    if (meta && e.key.toLowerCase() === "b") {
      e.preventDefault()
      wrapSelection("**", "**", "bold text")
      return
    }
    if (meta && e.key.toLowerCase() === "i") {
      e.preventDefault()
      wrapSelection("*", "*", "italic text")
      return
    }
    if (meta && e.key.toLowerCase() === "k") {
      e.preventDefault()
      insertLinkLike(false)
      return
    }
    if (e.key === "Tab") {
      e.preventDefault()
      const el = e.currentTarget
      const start = el.selectionStart
      const end = el.selectionEnd
      if (e.shiftKey) {
        const lineStart = value.lastIndexOf("\n", start - 1) + 1
        const removed = value.slice(lineStart, lineStart + 2) === "  " ? 2 : 0
        const next = value.slice(0, lineStart) + value.slice(lineStart + removed)
        setValue(next)
        focusTextarea(Math.max(lineStart, start - removed), Math.max(lineStart, end - removed))
      } else {
        const next = value.slice(0, start) + "  " + value.slice(end)
        setValue(next)
        focusTextarea(start + 2, end + 2)
      }
    }
  }

  const toolbarGroups: { icon: React.ComponentType<{ className?: string }>; label: string; shortcut?: string; onClick: () => void }[][] = [
    [
      { icon: Heading2, label: "Heading", onClick: () => prefixLines("## ") },
      { icon: Bold, label: "Bold", shortcut: "Ctrl+B", onClick: () => wrapSelection("**", "**", "bold text") },
      { icon: Italic, label: "Italic", shortcut: "Ctrl+I", onClick: () => wrapSelection("*", "*", "italic text") },
      { icon: Strikethrough, label: "Strikethrough", onClick: () => wrapSelection("~~", "~~", "strikethrough") },
    ],
    [
      { icon: Quote, label: "Quote", onClick: () => prefixLines("> ") },
      { icon: Code, label: "Inline code", onClick: () => wrapSelection("`", "`", "code") },
      { icon: Link2, label: "Link", shortcut: "Ctrl+K", onClick: () => insertLinkLike(false) },
      { icon: ImageIcon, label: "Image", onClick: () => insertLinkLike(true) },
    ],
    [
      { icon: List, label: "Bullet list", onClick: () => prefixLines("- ") },
      { icon: ListOrdered, label: "Numbered list", onClick: () => prefixLines("", true) },
      { icon: ListTodo, label: "Task list", onClick: () => prefixLines("- [ ] ") },
    ],
    [
      { icon: Code, label: "Code block", onClick: insertCodeBlock },
      { icon: TableIcon, label: "Table", onClick: insertTable },
      { icon: Minus, label: "Horizontal rule", onClick: insertHr },
    ],
  ]

  const charCount = value.length
  const wordCount = value.trim() === "" ? 0 : value.trim().split(/\s+/).length

  return (
    <>
      {fullscreen && (
        <div className="fixed inset-0 z-40 bg-black/40 backdrop-blur-sm" onClick={() => setFullscreen(false)} />
      )}
      <div
        className={cn(
          "flex flex-col overflow-hidden rounded-xl border bg-card shadow-sm",
          fullscreen && "fixed inset-4 z-50 shadow-2xl sm:inset-8",
          className
        )}
      >
        {/* Header: tabs + toolbar */}
        <div className="flex items-center justify-between gap-2 border-b bg-muted/30 px-2 py-1.5">
          <div className="flex items-center gap-1">
            <button
              type="button"
              onClick={() => setTab("write")}
              className={cn(
                "flex items-center gap-1.5 rounded-md px-2.5 py-1 text-xs font-medium transition-colors",
                tab === "write" ? "bg-background text-foreground shadow-sm" : "text-muted-foreground hover:text-foreground"
              )}
            >
              <Pencil className="h-3.5 w-3.5" />
              Write
            </button>
            <button
              type="button"
              onClick={() => setTab("preview")}
              className={cn(
                "flex items-center gap-1.5 rounded-md px-2.5 py-1 text-xs font-medium transition-colors",
                tab === "preview" ? "bg-background text-foreground shadow-sm" : "text-muted-foreground hover:text-foreground"
              )}
            >
              <Eye className="h-3.5 w-3.5" />
              Preview
            </button>
          </div>

          <div className="flex items-center gap-0.5">
            {tab === "write" &&
              toolbar &&
              toolbarGroups.map((group, gi) => (
                <React.Fragment key={gi}>
                  {gi > 0 && <ToolbarDivider />}
                  {group.map((action) => (
                    <ToolbarButton
                      key={action.label}
                      icon={action.icon}
                      label={action.label}
                      shortcut={action.shortcut}
                      onClick={action.onClick}
                      disabled={disabled}
                    />
                  ))}
                </React.Fragment>
              ))}

            <ToolbarDivider />
            <div className="relative" ref={helpRef}>
              <ToolbarButton icon={HelpCircle} label="Markdown cheatsheet" onClick={() => setHelpOpen((o) => !o)} />
              {helpOpen && (
                <div className="absolute right-0 z-10 mt-1.5 w-64 rounded-lg border bg-popover p-3 text-popover-foreground shadow-lg">
                  <p className="mb-2 text-xs font-semibold">Markdown cheatsheet</p>
                  <div className="space-y-1">
                    {CHEATSHEET.map((item) => (
                      <div key={item.syntax} className="flex items-center justify-between gap-2 text-xs">
                        <code className="rounded bg-muted px-1 py-0.5 font-mono text-[11px]">{item.syntax}</code>
                        <span className="text-muted-foreground">{item.result}</span>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
            <ToolbarButton
              icon={fullscreen ? Minimize2 : Maximize2}
              label={fullscreen ? "Exit fullscreen" : "Fullscreen"}
              onClick={() => setFullscreen((f) => !f)}
            />
          </div>
        </div>

        {/* Body */}
        {tab === "write" ? (
          <div className="relative flex-1">
            <textarea
              ref={textareaRef}
              value={value}
              onChange={(e) => setValue(e.target.value)}
              onKeyDown={handleKeyDown}
              onPaste={handlePaste}
              onDragOver={handleDragOver}
              onDragLeave={() => setIsDragActive(false)}
              onDrop={handleDrop}
              placeholder={placeholder}
              disabled={disabled}
              autoFocus={autoFocus}
              style={{ minHeight, height: fullscreen ? "100%" : minHeight }}
              className="w-full resize-none bg-transparent p-4 font-mono text-sm leading-relaxed outline-none placeholder:text-muted-foreground disabled:cursor-not-allowed disabled:opacity-60"
            />
            {isDragActive && (
              <div className="pointer-events-none absolute inset-2 flex items-center justify-center rounded-lg border-2 border-dashed border-primary bg-primary/5 text-sm font-medium text-primary">
                Drop image to upload
              </div>
            )}
          </div>
        ) : (
          <div
            style={{ minHeight, height: fullscreen ? "100%" : undefined }}
            className="flex-1 overflow-y-auto p-4"
          >
            {value.trim() ? (
              <MarkdownRenderer content={value} />
            ) : (
              <p className="text-sm text-muted-foreground">Nothing to preview.</p>
            )}
          </div>
        )}

        {/* Footer */}
        <div className="flex items-center justify-between gap-2 border-t bg-muted/20 px-3 py-1.5 text-[11px] text-muted-foreground">
          <span>Markdown is supported · paste or drop images to attach</span>
          <span className="font-mono">
            {charCount} chars · {wordCount} words
          </span>
        </div>
      </div>
    </>
  )
}

"use client"

import * as React from "react"
import { cn } from "@/lib/utils"

// ─── AST types ──────────────────────────────────────────────────────────────

type InlineNode =
  | { type: "text"; value: string }
  | { type: "strong"; children: InlineNode[] }
  | { type: "em"; children: InlineNode[] }
  | { type: "del"; children: InlineNode[] }
  | { type: "code"; value: string }
  | { type: "link"; href: string; title?: string; children: InlineNode[] }
  | { type: "image"; src: string; alt: string; title?: string }
  | { type: "break" }

type ListItem = { blocks: BlockNode[]; checked: boolean | null }

type Align = "left" | "center" | "right" | null

type BlockNode =
  | { type: "heading"; level: number; children: InlineNode[] }
  | { type: "paragraph"; children: InlineNode[] }
  | { type: "blockquote"; children: BlockNode[] }
  | { type: "code"; value: string; lang?: string }
  | { type: "list"; ordered: boolean; start?: number; items: ListItem[] }
  | { type: "hr" }
  | { type: "table"; header: InlineNode[][]; align: Align[]; rows: InlineNode[][][] }

// ─── Block-level parsing ────────────────────────────────────────────────────

function isNewBlockStart(line: string): boolean {
  return (
    /^\s{0,3}#{1,6}\s/.test(line) ||
    /^\s{0,3}(`{3,}|~{3,})/.test(line) ||
    /^\s{0,3}>/.test(line) ||
    /^\s{0,3}((-\s*){3,}|(\*\s*){3,}|(_\s*){3,})\s*$/.test(line) ||
    /^\s*([-*+]|\d+[.)])\s+/.test(line)
  )
}

function isTableSeparator(line: string): boolean {
  return /^\s*\|?\s*:?-{1,}:?\s*(\|\s*:?-{1,}:?\s*)*\|?\s*$/.test(line) && line.includes("-")
}

function splitTableRow(line: string): string[] {
  let t = line.trim()
  if (t.startsWith("|")) t = t.slice(1)
  if (t.endsWith("|") && !t.endsWith("\\|")) t = t.slice(0, -1)
  const cells: string[] = []
  let current = ""
  for (let idx = 0; idx < t.length; idx++) {
    const ch = t[idx]
    if (ch === "\\" && t[idx + 1] === "|") {
      current += "|"
      idx++
      continue
    }
    if (ch === "|") {
      cells.push(current.trim())
      current = ""
      continue
    }
    current += ch
  }
  cells.push(current.trim())
  return cells
}

function parseLines(lines: string[]): BlockNode[] {
  const blocks: BlockNode[] = []
  let i = 0

  while (i < lines.length) {
    const line = lines[i] ?? ""

    if (line.trim() === "") {
      i++
      continue
    }

    // Fenced code block.
    const fenceMatch = line.match(/^\s{0,3}(`{3,}|~{3,})\s*([^\s`]*)/)
    if (fenceMatch) {
      const fence = fenceMatch[1] ?? "```"
      const lang = fenceMatch[2] || undefined
      const fenceChar = fence[0] ?? "`"
      const fenceLen = fence.length
      const closeRe = new RegExp(`^\\s{0,3}\\${fenceChar}{${fenceLen},}\\s*$`)
      let j = i + 1
      const codeLines: string[] = []
      while (j < lines.length) {
        const current = lines[j] ?? ""
        if (closeRe.test(current)) {
          j++
          break
        }
        codeLines.push(current)
        j++
      }
      blocks.push({ type: "code", value: codeLines.join("\n"), lang })
      i = j
      continue
    }

    // ATX heading.
    const headingMatch = line.match(/^\s{0,3}(#{1,6})\s+(.*?)\s*#*\s*$/)
    if (headingMatch) {
      blocks.push({
        type: "heading",
        level: (headingMatch[1] ?? "#").length,
        children: parseInline(headingMatch[2] ?? ""),
      })
      i++
      continue
    }

    // Horizontal rule.
    if (/^\s{0,3}((-\s*){3,}|(\*\s*){3,}|(_\s*){3,})$/.test(line)) {
      blocks.push({ type: "hr" })
      i++
      continue
    }

    // Blockquote.
    if (/^\s{0,3}>/.test(line)) {
      const quoteLines: string[] = []
      let j = i
      while (j < lines.length) {
        const current = lines[j] ?? ""
        if (/^\s{0,3}>/.test(current)) {
          quoteLines.push(current.replace(/^\s{0,3}>\s?/, ""))
          j++
        } else if (current.trim() !== "" && !isNewBlockStart(current)) {
          quoteLines.push(current)
          j++
        } else {
          break
        }
      }
      blocks.push({ type: "blockquote", children: parseLines(quoteLines) })
      i = j
      continue
    }

    // GFM table.
    const nextLine = lines[i + 1]
    if (line.includes("|") && nextLine !== undefined && isTableSeparator(nextLine)) {
      const headerCells = splitTableRow(line)
      const align: Align[] = splitTableRow(nextLine).map((c) => {
        const t = c.trim()
        if (/^:-+:$/.test(t)) return "center"
        if (/^-+:$/.test(t)) return "right"
        if (/^:-+$/.test(t)) return "left"
        return null
      })
      let j = i + 2
      const rows: string[][] = []
      while (j < lines.length) {
        const current = lines[j]
        if (current === undefined || current.trim() === "" || !current.includes("|")) break
        rows.push(splitTableRow(current))
        j++
      }
      blocks.push({
        type: "table",
        header: headerCells.map((c) => parseInline(c)),
        align,
        rows: rows.map((r) => r.map((c) => parseInline(c))),
      })
      i = j
      continue
    }

    // List (ordered / unordered / task).
    const listMatch = line.match(/^(\s*)([-*+]|\d+[.)])\s+(.*)$/)
    if (listMatch) {
      const baseIndent = (listMatch[1] ?? "").length
      const ordered = /\d/.test(listMatch[2] ?? "")
      const startNum = ordered ? parseInt(listMatch[2] ?? "1", 10) : undefined
      const items: ListItem[] = []
      let j = i

      while (j < lines.length) {
        const current = lines[j] ?? ""
        const m = current.match(/^(\s*)([-*+]|\d+[.)])\s+(.*)$/)
        const indentLen = m ? (m[1] ?? "").length : -1
        if (!m || indentLen !== baseIndent || /\d/.test(m[2] ?? "") !== ordered) break

        const markerText = m[0] ?? ""
        const firstContent = m[3] ?? ""
        const contentIndent = markerText.length - firstContent.length
        const itemLines: string[] = [firstContent]
        let k = j + 1

        while (k < lines.length) {
          const lk = lines[k] ?? ""
          if (lk.trim() === "") {
            itemLines.push("")
            k++
            continue
          }
          const indentMatch = lk.match(/^(\s*)/)
          const indent = (indentMatch?.[1] ?? "").length
          const isSibling = /^(\s*)([-*+]|\d+[.)])\s+/.test(lk) && indent === baseIndent
          if (isSibling) break
          if (indent >= contentIndent) {
            itemLines.push(lk.slice(contentIndent))
            k++
          } else {
            break
          }
        }

        while (itemLines.length > 0 && itemLines[itemLines.length - 1] === "") itemLines.pop()

        let checked: boolean | null = null
        const firstLine = itemLines[0] ?? ""
        const taskMatch = firstLine.match(/^\[( |x|X)\]\s+(.*)$/)
        if (taskMatch) {
          checked = (taskMatch[1] ?? "").toLowerCase() === "x"
          itemLines[0] = taskMatch[2] ?? ""
        }

        items.push({ blocks: parseLines(itemLines), checked })
        j = k
      }

      blocks.push({ type: "list", ordered, start: startNum, items })
      i = j
      continue
    }

    // Paragraph — gather consecutive lines until a blank line or new block.
    const paraLines: string[] = [line]
    let j = i + 1
    while (j < lines.length) {
      const current = lines[j]
      if (current === undefined || current.trim() === "" || isNewBlockStart(current)) break
      const after = lines[j + 1]
      if (current.includes("|") && after !== undefined && isTableSeparator(after)) break
      paraLines.push(current)
      j++
    }
    blocks.push({ type: "paragraph", children: parseInline(paraLines.join("\n")) })
    i = j
  }

  return blocks
}

function parseBlocks(markdown: string): BlockNode[] {
  return parseLines(markdown.replace(/\r\n?/g, "\n").split("\n"))
}

// ─── Inline parsing ─────────────────────────────────────────────────────────

function matchLinkLike(
  text: string,
  bracketStart: number
): { label: string; href: string; title?: string; end: number } | null {
  if (text[bracketStart] !== "[") return null
  let i = bracketStart + 1
  let depth = 0
  const labelStart = i
  while (i < text.length) {
    const c = text[i]
    if (c === "\\") {
      i += 2
      continue
    }
    if (c === "[") depth++
    else if (c === "]") {
      if (depth === 0) break
      depth--
    }
    i++
  }
  if (text[i] !== "]") return null
  const label = text.slice(labelStart, i)
  i++
  if (text[i] !== "(") return null
  i++
  const parenStart = i
  let parenDepth = 0
  while (i < text.length) {
    const c = text[i]
    if (c === "\\") {
      i += 2
      continue
    }
    if (c === "(") parenDepth++
    else if (c === ")") {
      if (parenDepth === 0) break
      parenDepth--
    }
    i++
  }
  if (text[i] !== ")") return null
  const inside = text.slice(parenStart, i)
  i++
  const titleMatch = inside.match(/^(\S+)\s+"([^"]*)"\s*$/) ?? inside.match(/^(\S+)\s+'([^']*)'\s*$/)
  const href = titleMatch ? (titleMatch[1] ?? "") : inside.trim()
  const title = titleMatch ? titleMatch[2] : undefined
  return { label, href, title, end: i }
}

function matchDelimited(text: string, i: number, marker: string): { content: string; end: number } | null {
  if (!text.startsWith(marker, i)) return null
  const contentStart = i + marker.length
  let searchFrom = contentStart
  while (true) {
    const idx = text.indexOf(marker, searchFrom)
    if (idx === -1) return null
    if (idx === contentStart) {
      searchFrom = idx + marker.length
      continue
    }
    return { content: text.slice(contentStart, idx), end: idx + marker.length }
  }
}

function parseInline(text: string): InlineNode[] {
  const nodes: InlineNode[] = []
  let buffer = ""
  let i = 0

  const flush = () => {
    if (buffer) {
      nodes.push({ type: "text", value: buffer })
      buffer = ""
    }
  }

  while (i < text.length) {
    const ch = text[i] ?? ""

    // Hard break: two-or-more trailing spaces, or a backslash, before a newline.
    if (ch === " " && text[i + 1] === " " && text.slice(i).match(/^ {2,}\n/)) {
      flush()
      nodes.push({ type: "break" })
      const spaces = text.slice(i).match(/^ +/)?.[0]?.length ?? 2
      i += spaces + 1
      continue
    }
    if (ch === "\\" && text[i + 1] === "\n") {
      flush()
      nodes.push({ type: "break" })
      i += 2
      continue
    }
    if (ch === "\n") {
      flush()
      nodes.push({ type: "break" })
      i++
      continue
    }

    // Escaped character.
    if (ch === "\\" && /[\\`*_{}[\]()#+.!~>-]/.test(text[i + 1] ?? "")) {
      buffer += text[i + 1]
      i += 2
      continue
    }

    // Inline code span.
    if (ch === "`") {
      let fenceLen = 0
      while (text[i + fenceLen] === "`") fenceLen++
      const fence = "`".repeat(fenceLen)
      const closeIdx = text.indexOf(fence, i + fenceLen)
      if (closeIdx !== -1) {
        flush()
        nodes.push({ type: "code", value: text.slice(i + fenceLen, closeIdx).trim() })
        i = closeIdx + fenceLen
        continue
      }
    }

    // Image.
    if (ch === "!" && text[i + 1] === "[") {
      const m = matchLinkLike(text, i + 1)
      if (m) {
        flush()
        nodes.push({ type: "image", alt: m.label, src: m.href, title: m.title })
        i = m.end
        continue
      }
    }

    // Link.
    if (ch === "[") {
      const m = matchLinkLike(text, i)
      if (m) {
        flush()
        nodes.push({ type: "link", href: m.href, title: m.title, children: parseInline(m.label) })
        i = m.end
        continue
      }
    }

    // Autolink.
    if (ch === "<") {
      const m = text.slice(i).match(/^<(https?:\/\/[^\s>]+)>/)
      if (m) {
        flush()
        const href = m[1] ?? ""
        nodes.push({ type: "link", href, children: [{ type: "text", value: href }] })
        i += m[0].length
        continue
      }
    }

    // Strikethrough.
    if (text.startsWith("~~", i)) {
      const m = matchDelimited(text, i, "~~")
      if (m) {
        flush()
        nodes.push({ type: "del", children: parseInline(m.content) })
        i = m.end
        continue
      }
    }

    // Bold + italic.
    if (text.startsWith("***", i) || text.startsWith("___", i)) {
      const marker = text.slice(i, i + 3)
      const m = matchDelimited(text, i, marker)
      if (m) {
        flush()
        nodes.push({ type: "strong", children: [{ type: "em", children: parseInline(m.content) }] })
        i = m.end
        continue
      }
    }

    // Bold.
    if (text.startsWith("**", i) || text.startsWith("__", i)) {
      const marker = text.slice(i, i + 2)
      const m = matchDelimited(text, i, marker)
      if (m) {
        flush()
        nodes.push({ type: "strong", children: parseInline(m.content) })
        i = m.end
        continue
      }
    }

    // Italic.
    if (ch === "*" || ch === "_") {
      const prevChar = text[i - 1] ?? ""
      const isMidWordUnderscore = ch === "_" && /\w/.test(prevChar)
      if (!isMidWordUnderscore) {
        const m = matchDelimited(text, i, ch)
        if (m && !/^\s|\s$/.test(m.content)) {
          flush()
          nodes.push({ type: "em", children: parseInline(m.content) })
          i = m.end
          continue
        }
      }
    }

    buffer += ch
    i++
  }

  flush()
  return nodes
}

// ─── React rendering ────────────────────────────────────────────────────────

function renderInline(nodes: InlineNode[], keyPrefix: string): React.ReactNode[] {
  return nodes.map((node, idx) => {
    const key = `${keyPrefix}-${idx}`
    switch (node.type) {
      case "text":
        return node.value === "" ? null : <React.Fragment key={key}>{node.value}</React.Fragment>
      case "break":
        return <br key={key} />
      case "strong":
        return (
          <strong key={key} className="font-semibold text-foreground">
            {renderInline(node.children, key)}
          </strong>
        )
      case "em":
        return (
          <em key={key} className="italic">
            {renderInline(node.children, key)}
          </em>
        )
      case "del":
        return (
          <del key={key} className="text-muted-foreground line-through">
            {renderInline(node.children, key)}
          </del>
        )
      case "code":
        return (
          <code key={key} className="rounded bg-muted px-1.5 py-0.5 font-mono text-[0.85em] text-foreground">
            {node.value}
          </code>
        )
      case "link":
        return (
          <a
            key={key}
            href={node.href}
            title={node.title}
            target="_blank"
            rel="noopener noreferrer"
            className="font-medium text-primary underline underline-offset-2 hover:opacity-80"
          >
            {renderInline(node.children, key)}
          </a>
        )
      case "image":
        return (
          // eslint-disable-next-line @next/next/no-img-element
          <img
            key={key}
            src={node.src}
            alt={node.alt}
            title={node.title}
            className="my-2 inline-block max-w-full rounded-md border"
          />
        )
      default:
        return null
    }
  })
}

const HEADING_STYLES: Record<number, string> = {
  1: "text-2xl font-bold mt-6 mb-3 pb-2 border-b",
  2: "text-xl font-bold mt-6 mb-3 pb-2 border-b",
  3: "text-lg font-semibold mt-5 mb-2",
  4: "text-base font-semibold mt-4 mb-2",
  5: "text-sm font-semibold mt-3 mb-1",
  6: "text-sm font-semibold text-muted-foreground mt-3 mb-1",
}

function alignClass(align: Align): string {
  if (align === "center") return "text-center"
  if (align === "right") return "text-right"
  return "text-left"
}

function renderBlocks(blocks: BlockNode[], keyPrefix: string): React.ReactNode[] {
  return blocks.map((block, idx) => {
    const key = `${keyPrefix}-b${idx}`
    switch (block.type) {
      case "heading": {
        const Tag = `h${block.level}` as React.ElementType
        return (
          <Tag key={key} className={cn("scroll-m-20 first:mt-0", HEADING_STYLES[block.level])}>
            {renderInline(block.children, key)}
          </Tag>
        )
      }
      case "paragraph":
        return (
          <p key={key} className="leading-relaxed [&:not(:first-child)]:mt-3">
            {renderInline(block.children, key)}
          </p>
        )
      case "blockquote":
        return (
          <blockquote key={key} className="my-3 border-l-4 border-primary/30 pl-4 text-muted-foreground italic">
            {renderBlocks(block.children, key)}
          </blockquote>
        )
      case "code":
        return (
          <div key={key} className="my-3 overflow-hidden rounded-lg border bg-muted/50">
            {block.lang && (
              <div className="border-b bg-muted/60 px-3 py-1 font-mono text-[11px] text-muted-foreground">
                {block.lang}
              </div>
            )}
            <pre className="overflow-x-auto p-3 text-xs leading-relaxed">
              <code className="font-mono">{block.value}</code>
            </pre>
          </div>
        )
      case "hr":
        return <hr key={key} className="my-5 border-border" />
      case "list": {
        const Tag = (block.ordered ? "ol" : "ul") as React.ElementType
        return (
          <Tag
            key={key}
            start={block.ordered ? block.start : undefined}
            className={cn("my-3 ml-5 space-y-1.5", block.ordered ? "list-decimal" : "list-disc")}
          >
            {block.items.map((item, i) => (
              <li
                key={`${key}-i${i}`}
                className={cn(item.checked !== null && "flex items-start gap-2 -ml-5 list-none")}
              >
                {item.checked !== null && (
                  <input
                    type="checkbox"
                    checked={item.checked}
                    readOnly
                    disabled
                    className="mt-1.5 h-3.5 w-3.5 shrink-0 rounded border-muted-foreground/40 accent-primary"
                  />
                )}
                <div className="flex-1 [&>p]:m-0 [&>p]:inline">{renderBlocks(item.blocks, `${key}-i${i}`)}</div>
              </li>
            ))}
          </Tag>
        )
      }
      case "table":
        return (
          <div key={key} className="my-3 overflow-x-auto rounded-lg border">
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b bg-muted/40">
                  {block.header.map((cell, ci) => (
                    <th key={ci} className={cn("px-3 py-2 font-semibold", alignClass(block.align[ci] ?? null))}>
                      {renderInline(cell, `${key}-h${ci}`)}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {block.rows.map((row, ri) => (
                  <tr key={ri} className="border-b last:border-0 hover:bg-muted/20">
                    {row.map((cell, ci) => (
                      <td key={ci} className={cn("px-3 py-2", alignClass(block.align[ci] ?? null))}>
                        {renderInline(cell, `${key}-r${ri}c${ci}`)}
                      </td>
                    ))}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )
      default:
        return null
    }
  })
}

// ─── Public component ───────────────────────────────────────────────────────

export interface MarkdownRendererProps {
  /** Raw markdown source to render. */
  content: string
  /** Extra class names for the wrapping element. */
  className?: string
}

/**
 * MarkdownRenderer — renders a GitHub-flavored markdown subset (headings,
 * emphasis, strikethrough, inline/fenced code, links, images, autolinks,
 * block quotes, ordered/unordered/task lists, tables, and rules) straight
 * to React elements. No `dangerouslySetInnerHTML` — safe by construction.
 */
export function MarkdownRenderer({ content, className }: MarkdownRendererProps) {
  const blocks = React.useMemo(() => parseBlocks(content), [content])
  return <div className={cn("text-sm text-foreground", className)}>{renderBlocks(blocks, "root")}</div>
}
